#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int minValidStrings(std::vector<std::string>& words, std::string target) {
        int n = target.size();
        std::vector<int> max_jump(n, 0);

        for (const auto& w : words) {
            std::string s = w + '#' + target;
            int m = w.size();
            int total_len = s.size();
            std::vector<int> pi(total_len, 0);
            int j = 0;
            for (int i = 1; i < total_len; ++i) {
                while (j > 0 && s[i] != s[j]) j = pi[j - 1];
                if (s[i] == s[j]) j++;
                pi[i] = j;
            }

            for (int k = 0; k < n; ++k) {
                int match_len = pi[m + 1 + k];
                if (match_len > 0) {
                    int start_idx = k - match_len + 1;
                    if (match_len > max_jump[start_idx]) {
                        max_jump[start_idx] = match_len;
                    }
                }
            }
        }

        for (int i = 0; i < n - 1; ++i) {
            if (max_jump[i] - 1 > max_jump[i + 1]) {
                max_jump[i + 1] = max_jump[i] - 1;
            }
        }

        int jumps = 0, curr_end = 0, farthest = 0;
        for (int i = 0; i < n; ++i) {
            farthest = std::max(farthest, i + max_jump[i]);
            if (i == curr_end) {
                if (farthest == curr_end) return -1;
                jumps++;
                curr_end = farthest;
                if (curr_end >= n) return jumps;
            }
        }
        return curr_end >= n ? jumps : -1;
    }
};

import java.util.*;

class Solution {
    public int minValidStrings(String[] words, String target) {
        int n = target.length();
        int[] maxJump = new int[n];

        for (String w : words) {
            String s = w + "#" + target;
            int m = w.length();
            int totalLen = s.length();
            int[] pi = new int[totalLen];
            int j = 0;
            for (int i = 1; i < totalLen; i++) {
                while (j > 0 && s.charAt(i) != s.charAt(j)) j = pi[j - 1];
                if (s.charAt(i) == s.charAt(j)) j++;
                pi[i] = j;
            }

            for (int k = 0; k < n; k++) {
                int matchLen = pi[m + 1 + k];
                if (matchLen > 0) {
                    int startIdx = k - matchLen + 1;
                    if (matchLen > maxJump[startIdx]) {
                        maxJump[startIdx] = matchLen;
                    }
                }
            }
        }

        for (int i = 0; i < n - 1; i++) {
            if (maxJump[i] - 1 > maxJump[i + 1]) {
                maxJump[i + 1] = maxJump[i] - 1;
            }
        }

        int jumps = 0, currEnd = 0, farthest = 0;
        for (int i = 0; i < n; i++) {
            farthest = Math.max(farthest, i + maxJump[i]);
            if (i == currEnd) {
                if (farthest == currEnd) return -1;
                jumps++;
                currEnd = farthest;
                if (currEnd >= n) return jumps;
            }
        }
        return currEnd >= n ? jumps : -1;
    }
}

var minValidStrings = function(words, target) {
    const n = target.length;
    const maxJump = new Int32Array(n);

    for (const w of words) {
        const s = w + '#' + target;
        const m = w.length;
        const totalLen = s.length;
        const pi = new Int32Array(totalLen);
        let j = 0;
        for (let i = 1; i < totalLen; i++) {
            while (j > 0 && s[i] !== s[j]) j = pi[j - 1];
            if (s[i] === s[j]) j++;
            pi[i] = j;
        }

        for (let k = 0; k < n; k++) {
            const matchLen = pi[m + 1 + k];
            if (matchLen > 0) {
                const startIdx = k - matchLen + 1;
                if (matchLen > maxJump[startIdx]) {
                    maxJump[startIdx] = matchLen;
                }
            }
        }
    }

    for (let i = 0; i < n - 1; i++) {
        if (maxJump[i] - 1 > maxJump[i + 1]) {
            maxJump[i + 1] = maxJump[i] - 1;
        }
    }

    let jumps = 0, currEnd = 0, farthest = 0;
    for (let i = 0; i < n; i++) {
        if (i + maxJump[i] > farthest) farthest = i + maxJump[i];
        if (i === currEnd) {
            if (farthest === currEnd) return -1;
            jumps++;
            currEnd = farthest;
            if (currEnd >= n) return jumps;
        }
    }
    return currEnd >= n ? jumps : -1;
};
